, target AS (SELECT s.* FROM sessions s,input WHERE s.id=(args->>'session_id')::uuid)
SELECT jsonb_build_object(
 'session', (SELECT jsonb_build_object('id',id,'status',status,'computer_id',computer_id,'parent_session_id',parent_session_id,'created_at',created_at) FROM target),
 'processes', COALESCE((SELECT jsonb_agg(jsonb_build_object('epoch',p.epoch,'status',p.status,'computer_lease_epoch',p.computer_lease_epoch,'fenced_at',p.fenced_at) ORDER BY p.epoch) FROM session_processes p JOIN target s ON s.environment_id=p.environment_id AND s.id=p.session_id),'[]'::jsonb),
 'turns', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',t.id,'seq',t.seq,'status',t.status,'process_epoch',t.process_epoch,'created_at',t.created_at,'started_at',t.started_at,'terminal_at',t.terminal_at,'completion_save_id',t.completion_save_id) ORDER BY t.seq) FROM turns t JOIN target s ON s.environment_id=t.environment_id AND s.id=t.session_id),'[]'::jsonb),
 'checkpoints', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'process_epoch',m.process_epoch,'source_lease_epoch',c.source_lease_epoch,'target_lease_epoch',c.target_lease_epoch,'ready_at',c.ready_at,'controls_reconciled_at',c.controls_reconciled_at) ORDER BY c.created_at,c.id) FROM computer_checkpoint_members m JOIN target s ON s.environment_id=m.environment_id AND s.id=m.session_id JOIN computer_checkpoints c ON c.environment_id=m.environment_id AND c.id=m.checkpoint_id AND c.computer_id=s.computer_id),'[]'::jsonb));
